using IndieRun;
using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

static class Program
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static T Copy<T>(T value)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value))!;
    static void Hook(BackupEngine e,Action<string> hook)=>typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,hook);
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.GetValue(o)!;
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Refuse(Action action){try{action();}catch(Exception ex) when(ex is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException){return;}throw new Exception("Expected refusal");}
    static Package Fixture(string folder)
    {
        var path=Path.Combine(folder,"input","Bundle");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"generated fixture, do not run");
        foreach(var d in new[]{"Data","Comics","OtherGame","Scratch"}){Directory.CreateDirectory(Path.Combine(path,d));File.WriteAllText(Path.Combine(path,d,d=="OtherGame"?"Other.exe":"data.txt"),"fixture "+d);}
        Directory.CreateDirectory(Path.Combine(path,"Data","Empty"));return new(){IsReal=true,Registered=false,Id=Guid.NewGuid().ToString("N"),Source=path,DetectedRoot=path,SearchRoot=Path.Combine(folder,"input"),Folder="Bundle",Name="Bundle",Alias="작은 정원"};
    }
    static MainWindow Window(string folder,List<Package> packages,ScanSnapshot scan)
    {
        var w=new MainWindow();Set(w,"workspaceStore",new WorkspaceStore(Path.Combine(folder,"data","workspace.json")));Set(w,"packages",packages);Set(w,"selected",packages[0]);Set(w,"snapshot",scan);Set(w,"source",Path.Combine(folder,"input"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(folder,"input")}});Set(w,"destination",Path.Combine(folder,"library"));Set(w,"playerRoot",Path.Combine(folder,"library"));Set(w,"backupStorageRoot",Path.Combine(folder,"backups"));Set(w,"checkpoints",packages.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());return w;
    }
    static IEnumerable<DependencyObject> Visual(DependencyObject root){yield return root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var node in Visual(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return node;}
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    [STAThread]static int Main(string[] args)
    {
        if(args[0]=="--child")
        {
            var engine=new BackupEngine(args[1]);Hook(engine,stage=>{if(stage==args[4]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}});engine.MoveAsync(args[2],args[3]).GetAwaiter().GetResult();return 0;
        }
        if(args[0]=="--fixture")
        {
            var fixtureRoot=Path.GetFullPath(args[1]);var game=Fixture(fixtureRoot);game.Registered=true;var scan=GameScanner.Scan(game.SearchRoot);var lib=Path.Combine(fixtureRoot,"library");new LibraryStore(lib).Register(game,[],scan);scan=GameScanner.Scan(game.SearchRoot);
            var data=Path.Combine(fixtureRoot,"preview","data");Directory.CreateDirectory(data);new WorkspaceStore(Path.Combine(data,"workspace.json")).Save(new(){SearchRoot=game.SearchRoot,SearchLocations=[new(){Path=game.SearchRoot}],Destination=lib,BackupRoot=Path.Combine(fixtureRoot,"backups"),SelectedId=game.Id,IdentityNoticeAccepted=true,Packages=[game],Checkpoints=[WorkspaceReconciler.Capture(game,scan)]});new PlayerStore(lib).Save(new(){Games=[new(){Id=game.Id,Executable="Game.exe"}]});return 0;
        }
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(null);
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){var path=Path.Combine(root,name);Directory.CreateDirectory(path);try{action(path);results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        Test("exclude-guide-with-unowned-ancestor-candidate",folder=>{
            var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);
            var ancestor=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=p.SearchRoot,DetectedRoot=p.SearchRoot,SearchRoot=p.SearchRoot,Folder="input",Name="input"};
            File.WriteAllText(Path.Combine(ancestor.Source,"Launcher.exe"),"generated fixture");scan=GameScanner.Scan(p.SearchRoot);
            var draft=Copy(p);CompositionPlan.Assign(draft,Path.Combine(p.Source,"Scratch"),"exclude",new(),scan);
            var next=CompositionPlan.Apply(draft,[p,ancestor],scan);
            Check(next.Single(q=>q.Id==p.Id).OmittedFolders.Contains("Scratch"),"Guide exclusion did not apply");
            Check(next.Any(q=>q.Id==ancestor.Id),"Ancestor candidate was silently removed");
        });
        Test("draft-roles-write-no-game-files",folder=>{var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);var fingerprint=scan.Fingerprint();CompositionPlan.Assign(p,Path.Combine(p.Source,"Comics"),"related",new(),scan);CompositionPlan.Assign(p,Path.Combine(p.Source,"OtherGame"),"game",new(),scan);CompositionPlan.Assign(p,Path.Combine(p.Source,"Scratch"),"exclude",new(),scan);Check(GameScanner.Scan(p.SearchRoot).Fingerprint()==fingerprint,"Draft changed files");Check(p.OmittedFolders.Count==2&&p.Contents.Count==3,"Wrong plan");});
        Test("configured-launcher-and-work-folder-protected",folder=>{var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);Refuse(()=>CompositionPlan.Assign(p,Path.Combine(p.Source,"Data"),"exclude",new(){WorkingDirectory="Data"},scan));Refuse(()=>CompositionPlan.Assign(p,p.Source,"exclude",new(),scan));Refuse(()=>CompositionPlan.Assign(p,Path.Combine(p.Source,"OtherGame"),"exclude",new(){Executable="OtherGame/Other.exe"},scan));Check(p.Contents.Count==0,"Changed rejected plan");});
        Test("apply-separates-game-without-inheriting-main-tags",folder=>{var p=Fixture(folder);p.Genres=["冒険"];var scan=GameScanner.Scan(p.SearchRoot);CompositionPlan.Assign(p,Path.Combine(p.Source,"OtherGame"),"game",new(),scan);CompositionPlan.Assign(p,Path.Combine(p.Source,"Scratch"),"exclude",new(),scan);var next=CompositionPlan.Apply(p,[p],scan);Check(next.Count==3&&next.Single(q=>q.Folder=="OtherGame").Genres.Count==0&&next.Single(q=>q.Folder=="Scratch").Excluded,"Wrong split");var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,Destination=Path.Combine(folder,"library"),Packages=next,Checkpoints=next.Select(q=>WorkspaceReconciler.Capture(q,scan)).ToList()};WorkspaceStore.Validate(plan);new WorkspaceStore(Path.Combine(folder,"workspace.json")).Save(plan);Check(new WorkspaceStore(Path.Combine(folder,"workspace.json")).Load().Document!.Packages[0].OmittedFolders.Count==2,"Plan not persisted");});
        Test("existing-child-candidate-keeps-id-and-alias",folder=>{var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);var child=new Package{IsReal=true,Registered=false,Id=Guid.NewGuid().ToString("N"),Source=Path.Combine(p.Source,"OtherGame"),DetectedRoot=Path.Combine(p.Source,"OtherGame"),SearchRoot=p.SearchRoot,Folder="OtherGame",Name="OtherGame",Alias="既存"};CompositionPlan.Assign(p,child.Source,"game",new(),scan);var next=CompositionPlan.Apply(p,[p,child],scan);Check(next.Count==2&&next.Single(q=>q.Id==child.Id).Alias=="既存"&&next[0].Contents[0].Id==child.Id,"Existing game replaced");});
        Test("changing-draft-to-main-removes-omission",folder=>{var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);CompositionPlan.Assign(p,Path.Combine(p.Source,"Scratch"),"exclude",new(),scan);CompositionPlan.Assign(p,Path.Combine(p.Source,"Scratch"),"main",new(),scan);Check(p.Contents.Count==0&&p.OmittedFolders.Count==0,"Could not reset role");});
        Test("registered-separated-game-is-never-silently-merged",folder=>{var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);CompositionPlan.Assign(p,Path.Combine(p.Source,"OtherGame"),"game",new(),scan);var next=CompositionPlan.Apply(p,[p],scan);next[1].Registered=true;var draft=Copy(next[0]);draft.Contents=[];draft.OmittedFolders=[];Refuse(()=>CompositionPlan.Apply(draft,next,scan));});
        Test("links-stay-separate-by-default-and-optional-group-preserves-folder-names",folder=>{var p=Fixture(folder);var external=Path.Combine(folder,"input","Book");Directory.CreateDirectory(external);File.WriteAllText(Path.Combine(external,"guide.txt"),"guide");var scan=GameScanner.Scan(p.SearchRoot);p.RelatedFolders.Add(new(){Source=external,Name="Book"});var next=CompositionPlan.Apply(p,[p],scan);var target=Path.Combine(folder,"target");var moves=CompositionPlan.Expand([next[0]],next);Check(moves.Count==2&&moves.All(m=>Path.GetDirectoryName(CompositionPlan.Target(m,target))==target),"Default merged folders");next[0].RelatedFolders[0].Together=true;moves=CompositionPlan.Expand([next[0]],next);Check(moves.Select(m=>Path.GetDirectoryName(CompositionPlan.Target(m,target))).Distinct().Count()==1&&moves.Any(m=>m.Name=="Bundle")&&moves.Any(m=>m.Name=="Book"),"Grouping changes names");CompositionPlan.Preflight(new(Path.Combine(folder,"backups")),moves,target);});
        Test("external-link-refuses-overlap-and-registered-game",folder=>{var p=Fixture(folder);var other=Fixture(Path.Combine(folder,"other"));other.Registered=true;p.RelatedFolders.Add(new(){Source=other.Source,Name="Other"});Refuse(()=>CompositionPlan.Apply(p,[p,other],GameScanner.Scan(folder)));});
        Test("partial-backup-contains-only-moved-folders",folder=>{var p=Fixture(folder);p.OmittedFolders=["Scratch","OtherGame"];var e=new BackupEngine(Path.Combine(folder,"backups"));var backup=e.CreateAsync(p,[]).GetAwaiter().GetResult();Check(backup.Files.Count==3&&!backup.Files.Any(f=>f.RelativePath.StartsWith("Scratch")||f.RelativePath.StartsWith("OtherGame")),"Excluded files backed as main");e.VerifyAsync(backup.Id).GetAwaiter().GetResult();});
        Test("selective-move-and-undo-preserve-excluded-and-new-excluded-content",folder=>{var p=Fixture(folder);p.OmittedFolders=["Scratch","OtherGame"];var e=new BackupEngine(Path.Combine(folder,"backups"));var backup=e.CreateAsync(p,[]).GetAwaiter().GetResult();var target=Path.Combine(folder,"target","Bundle");var move=e.MoveAsync(backup.Id,target).GetAwaiter().GetResult();Check(move.Status=="Completed"&&File.Exists(Path.Combine(p.Source,"Scratch","data.txt"))&&!File.Exists(Path.Combine(p.Source,"Game.exe"))&&File.Exists(Path.Combine(target,"Game.exe"))&&!Directory.Exists(Path.Combine(target,"Scratch")),"Bad projected move");File.WriteAllText(Path.Combine(p.Source,"Scratch","new.txt"),"user change");e.UndoMoveAsync(backup.Id,move.Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(p.Source,"Game.exe"))&&File.ReadAllText(Path.Combine(p.Source,"Scratch","new.txt"))=="user change"&&!Directory.Exists(target),"Undo changed exclusions");});
        Test("selective-file-lock-rolls-back-main-and-keeps-excluded",folder=>{var p=Fixture(folder);p.OmittedFolders=["Scratch"];var e=new BackupEngine(Path.Combine(folder,"backups"));var backup=e.CreateAsync(p,[]).GetAwaiter().GetResult();using var held=new FileStream(Path.Combine(p.Source,"Data","data.txt"),FileMode.Open,FileAccess.Read,FileShare.Read);var target=Path.Combine(folder,"target","Bundle");try{e.MoveAsync(backup.Id,target).GetAwaiter().GetResult();throw new Exception("Expected lock failure");}catch(IOException){}Check(File.Exists(Path.Combine(p.Source,"Game.exe"))&&File.Exists(Path.Combine(p.Source,"Scratch","data.txt")),"Lock damaged original");});
        foreach(var point in new[]{"selective-intent","selective-published","selective-remove-file"})Test("process-kill-recovery-"+point,folder=>{var p=Fixture(folder);p.OmittedFolders=["Scratch","OtherGame"];var e=new BackupEngine(Path.Combine(folder,"backups"));var backup=e.CreateAsync(p,[]).GetAwaiter().GetResult();var target=Path.Combine(folder,"target","Bundle");var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,RedirectStandardOutput=true,CreateNoWindow=true};foreach(var a in new[]{"--child",e.Root,backup.Id,target,point})start.ArgumentList.Add(a);using var child=Process.Start(start)!;var line=child.StandardOutput.ReadLineAsync();Check(line.Wait(TimeSpan.FromSeconds(30))&&line.Result=="READY","Child did not reach crash point");child.Kill(true);child.WaitForExit();var pending=e.ListMoves().Single();e.ResumeMoveAsync(backup.Id,pending.Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(target,"Game.exe"))&&File.Exists(Path.Combine(p.Source,"Scratch","data.txt")),"Resume lost files");e.UndoMoveAsync(backup.Id,pending.Id).GetAwaiter().GetResult();Check(File.Exists(Path.Combine(p.Source,"Game.exe")),"Undo after resume failed");});
        Test("new-destination-file-stops-undo-without-overwrite",folder=>{var p=Fixture(folder);p.OmittedFolders=["Scratch"];var e=new BackupEngine(Path.Combine(folder,"backups"));var backup=e.CreateAsync(p,[]).GetAwaiter().GetResult();var target=Path.Combine(folder,"target","Bundle");var move=e.MoveAsync(backup.Id,target).GetAwaiter().GetResult();File.WriteAllText(Path.Combine(target,"user.txt"),"keep");Refuse(()=>e.UndoMoveAsync(backup.Id,move.Id).GetAwaiter().GetResult());Check(File.ReadAllText(Path.Combine(target,"user.txt"))=="keep"&&!File.Exists(Path.Combine(p.Source,"Game.exe")),"Undo changed user data");});
        Test("portable-roundtrip-keeps-related-role-and-links",folder=>{var p=Fixture(folder);p.ContentOwnerId=Guid.NewGuid().ToString("N");p.CompositionParentId=p.ContentOwnerId;p.Contents.Add(new(){Path="Comics",Role="related"});p.RelatedFolders.Add(new(){Source=Path.Combine(folder,"Book"),Name="Book",Together=true});LibraryStore.EnsureIdentity(p.Source,p.Id);PortableStore.Export(Path.GetDirectoryName(p.Source)!,p.Folder,p,new(){Id=p.Id},new(),Path.Combine(folder,"library"));var restored=Copy(p);restored.Contents=[];restored.RelatedFolders=[];PortableStore.Import(PortableStore.Read(p.Source)!,restored,new(),Path.Combine(folder,"fresh"));Check(restored.ContentOwnerId==p.ContentOwnerId&&restored.Contents.Single().Role=="related"&&restored.RelatedFolders.Single().Id==p.RelatedFolders[0].Id,"Relation lost");});
        Test("main-checkpoint-ignores-only-explicit-omissions",folder=>{var p=Fixture(folder);p.OmittedFolders=["Scratch"];var scan=GameScanner.Scan(p.SearchRoot);var baseline=WorkspaceReconciler.Capture(p,scan);File.WriteAllText(Path.Combine(p.Source,"Scratch","new.txt"),"new");WorkspaceReconciler.Check(p,baseline,GameScanner.Scan(p.SearchRoot));Check(p.ReviewState=="","Excluded content marked main changed");File.WriteAllText(Path.Combine(p.Source,"Data","new.txt"),"new");WorkspaceReconciler.Check(p,baseline,GameScanner.Scan(p.SearchRoot));Check(p.ReviewState=="changed","Main changes ignored");});
        Test("linked-content-can-be-shared-without-losing-first-owner",folder=>{var a=Fixture(folder);var b=Fixture(Path.Combine(folder,"second"));var book=Path.Combine(folder,"Book");Directory.CreateDirectory(book);a.RelatedFolders.Add(new(){Source=book,Name="Book"});var scan=GameScanner.Scan(folder);var next=CompositionPlan.Apply(a,[a,b],scan);b=next.Single(p=>p.Id==b.Id);b.RelatedFolders.Add(new(){Source=book,Name="Book"});var shared=CompositionPlan.Apply(b,next,scan);Check(ContentLinks.Owners(shared,a.RelatedFolders[0].Id).Count==2,"Sharing lost an owner");});
        Test("already-moved-component-is-skipped-when-retrying-parent",folder=>{var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);CompositionPlan.Assign(p,Path.Combine(p.Source,"OtherGame"),"game",new(),scan);var next=CompositionPlan.Apply(p,[p],scan);var target=Path.Combine(folder,"target");var child=next.Single(q=>q.Id!=p.Id);child.Source=Path.Combine(target,child.Name);var moving=CompositionPlan.Moving(CompositionPlan.Expand([next[0]],next),target);Check(moving.Count==1&&moving[0].Id==p.Id,"Retry includes completed component");Check(CompositionPlan.Moving(CompositionPlan.Expand([child],next),target).Count==1,"A directly selected game vanished from the plan");});
        Test("expanded-plan-preserves-edited-child-name-and-review-state",folder=>{var p=Fixture(folder);var book=Path.Combine(folder,"input","Book");Directory.CreateDirectory(book);p.RelatedFolders.Add(new(){Source=book,Name="Book",Together=true});var next=CompositionPlan.Apply(p,[p],GameScanner.Scan(p.SearchRoot));var first=CompositionPlan.Expand([next[0]],next);var child=first.Single(q=>q.ContentOwnerId==p.Id);child.Name="GuideBook";child.ReviewState="changed";var second=CompositionPlan.Expand(first,next);Check(second.Single(q=>q.Id==child.Id).Name=="GuideBook"&&second.Single(q=>q.Id==child.Id).ReviewState=="changed","Re-expansion lost edited plan or review");});
        Test("explicitly-omitted-executable-is-not-launchable",folder=>{var p=Fixture(folder);p.OmittedFolders=["OtherGame"];Refuse(()=>PlayerStore.StartInfo(p,new(){Executable="OtherGame/Other.exe"}));});
        foreach(var size in new[]{(784d,561d),(964d,691d)})Test("editor-layout-"+size.Item1,folder=>{var p=Fixture(folder);p.Alias=new string('長',150);var scan=GameScanner.Scan(p.SearchRoot);var w=Window(folder,[p],scan);Window? editor=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();editor=(Window)Call(w,"BuildCompositionEditor",p)!;var body=(FrameworkElement)editor.Content;body.Measure(new Size(size.Item1,size.Item2));body.Arrange(new Rect(0,0,size.Item1,size.Item2));body.UpdateLayout();var tree=Visual(body).OfType<TreeView>().Single();var apply=Visual(body).OfType<Button>().Single(b=>b.Name=="CompositionApply");var point=apply.TranslatePoint(new Point(),body);Check(tree.ActualHeight>200&&apply.ActualWidth>70&&point.X+apply.ActualWidth<=body.ActualWidth+.5&&point.Y+apply.ActualHeight<=body.ActualHeight+.5,"Editor actions clipped");Check(!apply.IsEnabled,"Unchanged draft can apply");}finally{editor?.Close();Close(w);}});
        Test("editor-can-restore-an-excluded-folder-after-rescan",folder=>{var p=Fixture(folder);var all=GameScanner.Scan(p.SearchRoot);CompositionPlan.Assign(p,Path.Combine(p.Source,"Scratch"),"exclude",new(),all);var next=CompositionPlan.Apply(p,[p],all);var partial=GameScanner.Scan(p.SearchRoot,[Path.Combine(p.Source,"Scratch")]);var w=Window(folder,next,partial);Window? editor=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"compositionSnapshot",all);editor=(Window)Call(w,"BuildCompositionEditor",next[0])!;var root=(FrameworkElement)editor.Content;root.Measure(new Size(964,691));root.Arrange(new Rect(0,0,964,691));root.UpdateLayout();var tree=Visual(root).OfType<TreeView>().Single();var item=((TreeViewItem)tree.Items[0]).Items.OfType<TreeViewItem>().Single(n=>(string?)n.Tag==Path.Combine(p.Source,"Scratch"));item.IsSelected=true;root.UpdateLayout();Visual(root).OfType<Button>().Single(b=>b.Content?.ToString()=="본편에 포함").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));root.UpdateLayout();Check(Visual(root).OfType<Button>().Single(b=>b.Name=="CompositionApply").IsEnabled,"Excluded folder cannot be restored");Visual(root).OfType<Button>().Single(b=>b.Content?.ToString()=="포함하지 않음").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!Visual(root).OfType<Button>().Single(b=>b.Name=="CompositionApply").IsEnabled,"Restored initial draft considered dirty");}finally{editor?.Close();Close(w);}});
        Test("full-wpf-batch-split-and-related-content",folder=>
        {
            SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));
            var p=Fixture(folder);var scan=GameScanner.Scan(p.SearchRoot);CompositionPlan.Assign(p,Path.Combine(p.Source,"OtherGame"),"game",new(),scan);CompositionPlan.Assign(p,Path.Combine(p.Source,"Scratch"),"exclude",new(),scan);var book=Path.Combine(folder,"input","Book");Directory.CreateDirectory(book);File.WriteAllText(Path.Combine(book,"guide.txt"),"guide");scan=GameScanner.Scan(p.SearchRoot);p.RelatedFolders.Add(new(){Source=book,Name="Book"});var next=CompositionPlan.Apply(p,[p],scan);var w=Window(folder,next,scan);
            try{Set(w,"workspaceLock",Get<WorkspaceStore>(w,"workspaceStore").AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);Wait((Task)Call(w,"StartMoveBatchAsync",new List<Package>{next[0]},Path.Combine(folder,"target"))!);var moves=new BackupEngine(Path.Combine(folder,"backups")).ListMoves();Check(moves.Count==2&&moves.All(m=>m.Status=="Completed"),"Composition batch not completed");Check(File.Exists(Path.Combine(folder,"target","Bundle","Game.exe"))&&File.Exists(Path.Combine(p.Source,"OtherGame","Other.exe"))&&File.Exists(Path.Combine(folder,"target","Book","guide.txt"))&&File.Exists(Path.Combine(p.Source,"Scratch","data.txt")),"Wrong physical layout");Check(Get<List<Package>>(w,"packages").Single(q=>q.ContentOwnerId==p.Id).Source==Path.Combine(folder,"target","Book"),"Link did not follow move");Wait((Task)Call(w,"SyncMovedPackagesAsync")!);var main=Get<List<Package>>(w,"packages").Single(q=>q.Id==p.Id);main.Contents.Add(new(){Path="Data",Role="related"});Wait((Task)Call(w,"SyncMovedPackagesAsync")!);Check(main.Contents.Any(c=>c.Path=="Data"),"Old move erased a later composition edit");main.Contents.RemoveAll(c=>c.Path=="Data");Wait((Task)Call(w,"RefreshWorkspaceAsync",p.SearchRoot,false,false)!);Check(Get<List<Package>>(w,"packages").Where(q=>!q.Excluded).All(q=>q.ReviewState.Length==0),"Moved destination not scanned or baseline changed: "+string.Join(" | ",Get<List<Package>>(w,"packages").Where(q=>!q.Excluded).Select(q=>q.Folder+" ["+q.ReviewState+"] "+q.ReviewReason+" "+string.Join(";",q.ReviewDetails))));}finally{Close(w);}
        });
        Test("full-grouped-move-keeps-physical-names-and-selected-rename",folder=>{var p=Fixture(folder);var book=Path.Combine(folder,"input","Book");Directory.CreateDirectory(book);File.WriteAllText(Path.Combine(book,"guide.txt"),"guide");p.RelatedFolders.Add(new(){Source=book,Name="Book",Together=true});var scan=GameScanner.Scan(p.SearchRoot);var next=CompositionPlan.Apply(p,[p],scan);var moves=CompositionPlan.Expand([next[0]],next);moves.Single(q=>q.ContentOwnerId==p.Id).Name="GuideBook";var w=Window(folder,next,scan);try{Set(w,"workspaceLock",Get<WorkspaceStore>(w,"workspaceStore").AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);var target=Path.Combine(folder,"target");Wait((Task)Call(w,"StartMoveBatchAsync",moves,target)!);Check(File.Exists(Path.Combine(target,"Bundle_bundle","Bundle","Game.exe"))&&File.Exists(Path.Combine(target,"Bundle_bundle","GuideBook","guide.txt")),"Grouped placement or rename incorrect");Check(Get<List<Package>>(w,"packages").Single(q=>q.Id==p.Id).RelatedFolders.Single().Name=="GuideBook","Renamed relationship not updated");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT {results.Count-failed}/{results.Count}");return failed==0?0:1;
    }
}
